+        throws IOException {
+        Analyzer analyzer = new Analyzer() {
+            @Override
+            protected TokenStreamComponents createComponents(String fieldName) {
+                WhitespaceTokenizer tokenizer = new WhitespaceTokenizer();
+                TokenStream stream = new BasicTokenFilter(
