+                    Character.FORMAT,
+                    Character.FORMAT,
+                    'b',
+                    'b',
+                    Character.CONTROL,
+                    'c',
+                    'c',
+                    Character.CONTROL,
+                    Character.CONTROL }
+            )
+        );
+        char[] output = new char[10];
+        int read = controlCharFilter.read(output, 0, 10);
+        assertThat(read, equalTo(5));
+        assertThat(new String(output, 0, read), equalTo("abbcc"));
