+
+    public void testCorrectForLongString() throws IOException {
+        char[] charArray = new char[2000];
+        int i = 0;
+        for (; i < 1000; i++) {
+            charArray[i] = 'a';
+        }
+        charArray[i++] = Character.CONTROL;
+        charArray[i++] = Character.CONTROL;
+        for (int j = 0; j < 997; j++) {
+            charArray[i++] = 'a';
+        }
+        charArray[i] = Character.CONTROL;
+        ControlCharFilter controlCharFilter = new ControlCharFilter(new CharArrayReader(charArray));
